    data: atual.data,
    horario: atual.horario
  }
}];

const dados = $("Resolver contexto conversa").first().json;

let horario = dados.horario;
let data = dados.data;

// Texto original
const texto = dados.mensagem
  .toLowerCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "");

// Horário: 17:00 -> 17:00:00
if (horario && horario.length === 5) {
  horario = `${horario}:00`;
}

// Data/hora atual em São Paulo
const hoje = DateTime.now()
  .setZone("America/Sao_Paulo")
  .startOf("day");

// ========================================
// DATA DETERMINÍSTICA
// ========================================

// HOJE
if (/\bhoje\b/.test(texto)) {
  data = hoje.toISODate();
}

// AMANHÃ
else if (/\bamanha\b/.test(texto)) {
  data = hoje.plus({ days: 1 }).toISODate();
}

// DIAS DA SEMANA
else {
  const diasSemana = {
    "domingo": 7,
    "segunda": 1,
    "segunda-feira": 1,
    "terca": 2,
    "terca-feira": 2,
    "quarta": 3,
    "quarta-feira": 3,
    "quinta": 4,
    "quinta-feira": 4,
    "sexta": 5,
    "sexta-feira": 5,
    "sabado": 6
  };

  let diaEncontrado = null;

  for (const [nome, numero] of Object.entries(diasSemana)) {
    if (texto.includes(nome)) {
      diaEncontrado = numero;
      break;
    }
  }

  if (diaEncontrado !== null) {
    let diferenca = diaEncontrado - hoje.weekday;

    // Se for hoje ou um dia já passado nesta semana,
    // considera a próxima ocorrência.
    if (diferenca <= 0) {
      diferenca += 7;
    }

    data = hoje.plus({ days: diferenca }).toISODate();
  }
}

// Se veio da IA como "2026-08-29 17:00",
// mantém só YYYY-MM-DD
if (data) {
  data = String(data).substring(0, 10);
}

return [{
  json: {
    empresa_id: dados.empresa_id,
    nome: dados.nome,
    telefone: dados.telefone,
    mensagem: dados.mensagem,
    servico: dados.servico,
    data,
    horario
  }
}];

